import AsyncStorage from '@react-native-async-storage/async-storage';
import { createAudioPlayer, type AudioPlayer } from 'expo-audio';
import * as Haptics from 'expo-haptics';
import { Platform } from 'react-native';

/** Generated by scripts/make-sounds.py. */
const SOURCES = {
  tap: require('@/assets/sounds/tap.wav'),
  send: require('@/assets/sounds/send.wav'),
  offer: require('@/assets/sounds/offer.wav'),
  success: require('@/assets/sounds/success.wav'),
  step: require('@/assets/sounds/step.wav'),
  complete: require('@/assets/sounds/complete.wav'),
  error: require('@/assets/sounds/error.wav'),
} as const;

export type SoundName = keyof typeof SOURCES;

const HAPTICS: Partial<Record<SoundName, () => Promise<void>>> = {
  tap: () => Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light),
  send: () => Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Medium),
  offer: () => Haptics.notificationAsync(Haptics.NotificationFeedbackType.Success),
  success: () => Haptics.notificationAsync(Haptics.NotificationFeedbackType.Success),
  step: () => Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light),
  complete: () => Haptics.notificationAsync(Haptics.NotificationFeedbackType.Success),
  error: () => Haptics.notificationAsync(Haptics.NotificationFeedbackType.Error),
};

const STORAGE_KEY = 'xapp.soundOn';
const players: Partial<Record<SoundName, AudioPlayer>> = {};
let enabled = true;
const listeners = new Set<(on: boolean) => void>();

AsyncStorage.getItem(STORAGE_KEY)
  .then((saved) => {
    if (saved === 'false') setSoundEnabled(false);
  })
  .catch(() => {});

export function soundEnabled() {
  return enabled;
}

export function setSoundEnabled(on: boolean) {
  enabled = on;
  AsyncStorage.setItem(STORAGE_KEY, String(on)).catch(() => {});
  listeners.forEach((listener) => listener(on));
}

export function onSoundSetting(listener: (on: boolean) => void) {
  listeners.add(listener);
  return () => {
    listeners.delete(listener);
  };
}

/** Plays a UI sound (and a matching haptic on phones). Never throws. */
export function play(name: SoundName) {
  if (Platform.OS !== 'web') HAPTICS[name]?.().catch(() => {});
  if (!enabled) return;
  try {
    let player = players[name];
    if (!player) {
      player = createAudioPlayer(SOURCES[name]);
      player.volume = name === 'tap' ? 0.4 : 0.8;
      players[name] = player;
    }
    player.seekTo(0).catch(() => {});
    player.play();
  } catch {
    // Audio can be unavailable (e.g. before the first tap on the web); stay silent.
  }
}
